"""Atlas contrafactual europeo. Geometrías generalizadas; no fronteras de un tratado real."""
import sys,json,html
from pathlib import Path
ROOT=Path(__file__).parent
sys.path.insert(0,str(ROOT.parent/'potencias-centrales/.libs'))
from shapely.geometry import shape,Polygon,box,mapping
from shapely import make_valid,set_precision
from shapely.ops import unary_union
from pyproj import Transformer
D={y:json.loads((ROOT/f'datos/world_{y}.geojson').read_text(encoding='utf-8')) for y in [1914,1938,1994]}
def get(y,*names):
 return unary_union([make_valid(shape(f['geometry'])) for f in D[y]['features'] if f['properties'].get('NAME') in names])
clip=box(-15,29,61,71)
P=Transformer.from_crs('EPSG:4326','+proj=lcc +lat_1=35 +lat_2=65 +lat_0=50 +lon_0=20 +datum=WGS84',always_xy=True).transform
def xy(lon,lat):
 x,y=P(lon,lat);return 790+x/4900,575-y/4900
C={'reich':'#65747d','occupation':'#b6c4c9','east':'#b59a7c','italy':'#819b75','italian':'#b7c9a5','ally':'#c6ab66','client':'#d1b58e','neutral':'#d9d3c1','russia':'#bda897','britain':'#bd969a'}
regions=[]
def add(name,g,cat,note,approx=False,project=False):
 g=set_precision(make_valid(g).buffer(0),.00001).intersection(clip).buffer(0)
 if g.is_empty:return
 # Cada territorio nuevo sustituye al anterior; el GeoJSON final queda sin solapamientos.
 for r in regions:
  if not r['g'].is_empty:r['g']=r['g'].difference(g).buffer(0)
 regions.append(dict(name=name,g=g,category=cat,color=C[cat],note=note,approx=approx,project=project))
names={'Germany':'Reich alemán','United Kingdom':'Reino Unido','Ireland':'Irlanda','France':'Francia','Italy':'Italia','Spain':'España','Portugal':'Portugal','Switzerland':'Suiza','Turkey':'Turquía','Sweden':'Suecia','Norway':'Noruega','Finland':'Finlandia','Denmark':'Dinamarca','Netherlands':'Países Bajos','Belgium':'Bélgica','Poland':'Polonia ocupada','Czechoslovakia':'Checoslovaquia: reparto posterior','Romania':'Rumanía','Hungary':'Hungría','Bulgaria':'Bulgaria','Yugoslavia':'Yugoslavia: reparto posterior','Greece':'Grecia','Albania':'Albania','USSR':'Espacio soviético residual','Luxembourg':'Luxemburgo','Libya':'Libia italiana','Tunisia':'Túnez','Egypt':'Egipto','Algeria (France)':'Argelia francesa','Morocco (France)':'Marruecos francés','Mandatory Palestine (GB)':'Palestina bajo mandato','Syria (France)':'Siria bajo mandato','Mesopotamia (GB)':'Irak'}
for f in D[1938]['features']:
 n=f['properties'].get('NAME') or 'Territorio sin identificar'
 if not f.get('geometry'):continue
 g=make_valid(shape(f['geometry']))
 if not g.intersects(clip):continue
 cat='neutral';note='Se mantiene como referencia territorial. No se presupone su incorporación al Eje.'
 if n=='Germany':cat='reich';note='Base alemana de 1938, que incluye Austria y las incorporaciones de ese año. En este escenario se conserva el régimen nazi.'
 if n in ['Italy','Libya']:cat='italy';note='Italia fascista conserva su Estado y su posición imperial. Libia se representa como colonia italiana.'
 if n in ['Romania','Hungary','Bulgaria','Finland']:cat='ally';note='Estado aliado o cobeligerante, con gobierno propio y dependencia variable. Finlandia no se equipara a una provincia alemana.'
 if n in ['Norway','Denmark','Netherlands','Belgium','Poland']:cat='occupation';note='Se prolonga hipotéticamente la ocupación o subordinación alemana; no se interpreta como anexión automática.'
 if n in ['France','Yugoslavia']:cat='client';note='El escenario supone una reorganización sometida al Eje. El color no implica soberanía plena.'
 if n in ['Albania','Greece']:cat='italian';note='Control italiano o tutela del Eje prolongados hipotéticamente. Grecia no se representa como anexión íntegra de Italia.'
 if n=='Luxembourg':cat='reich';note='La incorporación de hecho al Reich durante la guerra se mantiene en este escenario.'
 if n=='United Kingdom':cat='britain';note='Hipótesis explícita: paz negociada con Londres, sin invasión ni anexión de las islas británicas. No era un desenlace asegurado.'
 if n=='USSR':cat='russia';note='Territorio soviético o sucesor fuera de la administración alemana propuesta. Su régimen y su límite occidental quedan sin resolver.'
 add(names.get(n,n),g,cat,note)
add('Alsacia y Mosela · incorporación de hecho',get(1914,'German Empire').intersection(get(1938,'France')),'reich','Se prolonga la anexión de hecho aplicada durante la ocupación nazi. Se emplea la intersección de las capas de 1914 y 1938 para aproximar Alsacia-Mosela.',True)
add('Memel · incorporación al Reich',get(1914,'German Empire').intersection(get(1938,'Lithuania')),'reich','Se prolonga la incorporación alemana de Memel de 1939. Geometría histórica generalizada.',True)
# Corregir una anomalía de la base de 1938: una Armenia sobredimensionada invade Turquía.
add('Turquía',get(1994,'Turkey'),'neutral','Frontera oriental corregida con una capa posterior: Turquía sigue fuera del reparto supuesto.')
add('Cáucaso soviético',get(1994,'Armenia','Georgia','Azerbaijan'),'russia','Referencia geográfica para el proyecto caucásico, sin asumir que estos Estados independientes existan en 1948.')
cz=get(1938,'Czechoslovakia');sk=get(1994,'Slovakia').intersection(cz);ruth=cz.intersection(box(22.15,47,25,50))
add('Rutenia subcarpática: incorporación húngara',ruth,'ally','Se prolonga la incorporación húngara de 1939. Delimitación simplificada.',True)
add('Eslovaquia',sk.difference(ruth),'client','Se supone la continuidad del Estado eslovaco dependiente de Alemania, sin equipararlo a una anexión al Reich.',True)
add('Protectorado de Bohemia y Moravia',cz.difference(sk).difference(ruth),'occupation','Se mantiene una administración alemana diferenciada. El contorno se deriva del resto de Checoslovaquia de 1938 y no reproduce cada rectificación local.',True)
pol=get(1938,'Poland')
annex=pol.intersection(Polygon([(14,49),(18.8,49),(19.6,50.3),(18.8,51.2),(19.5,52),(19,53.2),(20.4,54),(20.4,56),(14,56)]))
add('Territorios polacos incorporados al Reich',annex,'reich','Esquema de las anexiones del oeste y norte de Polonia, incluido el corredor hacia Prusia Oriental. El trazo no reproduce exactamente los límites de los Reichsgaue.',True)
eastland=unary_union([get(1938,'Estonia','Latvia','Lithuania'),get(1994,'Byelarus').intersection(unary_union([get(1938,'USSR'),pol]))]).difference(get(1914,'German Empire').intersection(get(1938,'Lithuania')))
ukraine=get(1994,'Ukraine').intersection(unary_union([get(1938,'USSR'),pol]));ukraine=ukraine.difference(get(1938,'Romania'))
add('Ostland · administración alemana',eastland,'east','Inspirado en el Reichskommissariat Ostland realmente establecido. Los contornos de las unidades de 1994 solo aproximan su espacio; no representan Estados bálticos independientes.',True)
add('Ucrania · administración alemana',ukraine,'east','Se supone una administración colonial alemana ampliada. Incluye aquí Crimea de forma hipotética; Galicia y otras subdivisiones de guerra se generalizan. No se dibuja una Ucrania soberana.',True)
add('Crimea* · régimen colonial proyectado',ukraine.intersection(Polygon([(32,44),(37,44),(37,45.8),(35,46.2),(33,46.2),(32,45.4)])),'east','Hipótesis de control y colonización alemana de Crimea. El estatuto final y su relación con Ucrania no estaban fijados en un tratado de posguerra.',True,True)
remaining=pol.difference(annex).difference(eastland).difference(ukraine)
add('Gobierno General · Polonia ocupada',remaining,'occupation','Administración colonial alemana separada del Reich. División territorial generalizada; su existencia no implica autonomía política polaca.',True)
# Repartos balcánicos, aproximados a escala continental.
yug=get(1938,'Yugoslavia');slov=get(1994,'Slovenia').intersection(yug)
add('Croacia y Bosnia · Estado dependiente',get(1994,'Croatia','Bosnia and Herzegovina').intersection(yug),'client','Continuidad hipotética del Estado ustacha que incluía Bosnia-Herzegovina. Las fronteras modernas sirven de guía aproximada; hubo cesiones costeras a Italia.',True)
add('Eslovenia septentrional',slov.intersection(box(13,46.05,17,48)),'reich','Se prolonga la incorporación alemana de parte de Eslovenia. División aproximada, no frontera administrativa exacta.',True)
add('Eslovenia meridional',slov.intersection(box(13,44,17,46.05)),'italy','Parte de Eslovenia bajo Italia según el reparto de 1941, generalizada.',True)
add('Serbia · ocupación alemana',get(1994,'Serbia').intersection(yug),'occupation','Se mantiene una Serbia reducida bajo ocupación alemana; incluye simplificaciones del Banato y de las áreas repartidas.',True)
mac=get(1994,'Macedonia').intersection(yug)
add('Macedonia del Vardar: zona búlgara',mac.intersection(box(20.8,40,24,44)),'ally','Continuidad hipotética de la expansión búlgara. Macedonia occidental se integra aquí en la zona italiana-albanesa.',True)
add('Albania ampliada bajo Italia',unary_union([get(1938,'Albania'),mac.intersection(box(19,40,20.8,44)),yug.intersection(box(20,41.8,20.9,43))]),'italian','Se prolonga la tutela italiana y se esquematizan las incorporaciones en Kosovo y Macedonia occidental.',True)
add('Montenegro · tutela italiana',yug.intersection(box(18.4,41.8,20,43.5)),'italian','Zona de control italiano esquematizada, sin asumir una anexión completa.',True)
dal=Polygon([(14,45.6),(14.8,44.5),(16,43.4),(17.6,42.5),(18,42.7),(16.4,43.9),(15.6,45),(14.5,46)])
add('Dalmacia: enclaves y costa italianos',yug.intersection(dal),'italy','Representación simplificada de zonas costeras italianas. No reproduce las discontinuidades de las cesiones de 1941.',True)
backa=yug.intersection(Polygon([(18.3,46.3),(20.4,46.3),(20.4,45.15),(19,45.15),(18.3,45.6)]))
add('Bačka y Baranja: ampliación húngara',backa,'ally','Esquema de las incorporaciones húngaras en el reparto yugoslavo de 1941.',True)
rom=get(1938,'Romania')
add('Transilvania septentrional',rom.intersection(Polygon([(21.5,47.8),(24.8,48.2),(26.2,46.9),(25.4,46),(23.5,46.5),(22.2,47)])),'ally','Se prolonga el reparto favorable a Hungría de 1940. El contorno es aproximado.',True)
add('Dobruja meridional',rom.intersection(Polygon([(27,43.5),(29,43.5),(29,44.2),(28,44.2),(27,44)])),'ally','Cesión a Bulgaria de 1940 mantenida hipotéticamente; contorno generalizado.',True)
add('Tracia y Macedonia oriental: zona búlgara',get(1938,'Greece').intersection(box(23.7,40.65,26.6,42)),'ally','Prolongación hipotética de la administración búlgara de guerra. No equivale a una adjudicación internacional definitiva.',True)
add('Transnistria · administración rumana',ukraine.intersection(Polygon([(27.2,48.4),(28.5,48.5),(31.3,47.1),(31.5,46.3),(29.5,45.8),(28.7,46.5)])),'ally','Área de administración rumana entre Dniéster y Bug, muy generalizada. Ocupación administrativa no equivale a anexión reconocida.',True)
# Proyectos que no llegaron a constituirse: color de ocupación, trama y borde discontinuo.
ussr=get(1938,'USSR')
mos=ussr.intersection(Polygon([(29,61.5),(35,63),(43,62),(49,59),(49,53),(44,49),(38,49),(33,52),(30,57)]))
add('Moscovia* · administración proyectada',mos.difference(eastland).difference(ukraine),'east','Hipótesis de expansión alemana tras una derrota soviética. Un comisariado central fue proyectado, pero este contorno se ha construido para el escenario y no corresponde a una frontera aprobada.',True,True)
cauc=unary_union([get(1994,'Georgia','Armenia','Azerbaijan'),ussr.intersection(Polygon([(36,45.5),(42,47.5),(49,46.5),(51,42),(46,40),(39,41)]))])
add('Cáucaso* · administración proyectada',cauc.difference(ukraine),'east','Proyecto de subordinación del Cáucaso a Alemania. Administración y fronteras hipotéticas; no llegó a establecerse un Reichskommissariat Kaukasien operativo.',True,True)
add('Carelia oriental* · aspiración finlandesa',ussr.intersection(Polygon([(30,61),(32,61),(35,62),(35.5,64.5),(33,65.5),(30,64)])),'ally','Expansión hipotética más allá de la recuperación de las fronteras finlandesas anteriores a la Guerra de Invierno. No se presupone una anexión acordada.',True,True)
claims=[('Córcega* · pretensión italiana',get(1938,'France').intersection(box(8,41,10,43.2))),('Túnez* · pretensión italiana',get(1938,'Tunisia')),('Niza* · pretensión italiana',get(1938,'France').intersection(box(7,43.4,7.7,44.3)))]
for name,g in claims:add(name,g,'italian','Reclamación o ámbito de ambición italiana representado como proyecto, sin asumir un tratado final de cesión.',True,True)
