def path(g):
 if g.geom_type=='Polygon':
  return ' '.join('M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in [xy(*p[:2]) for p in ring.coords])+' Z' for ring in [g.exterior,*g.interiors])
 return ' '.join(path(q) for q in g.geoms) if hasattr(g,'geoms') else ''
def text(x,y,t,size=16,anchor='start',cls=''):
 return f'<text x="{x}" y="{y}" font-size="{size}" text-anchor="{anchor}" class="{cls}">{html.escape(t)}</text>'
