labels=[('REICH ALEMÁN',11,51.2,23),('ITALIA',12.5,42,21),('REINO UNIDO',-3,55,19),('Irlanda',-8,53,16),('Francia sometida',2,46.5,19),('Ostland',27.5,56.8,21),('Ucrania ocupada',32,49,20),('Moscovia*',40,57,24),('Cáucaso*',44,43,22),('Espacio soviético',53,58,18),('o sucesor residual',53,56.6,16),('Finlandia',25,64,19),('Noruega',7,64,18),('Suecia',16,63,18),('España',-2.5,40,20),('Portugal',-10.2,39.3,15),('Turquía',33,39,20),('Libia italiana',18,31,19),('Túnez*',9.5,34.5,16),('Egipto',29.5,31,18),('Hungría',19.5,47.4,16),('Rumanía',25,45.4,17),('Bulgaria',25.5,42.6,17),('Croacia',16.8,44.7,15),('Serbia',20.7,44.1,15),('Grecia',23.5,38,16),('Albania',19.3,40.6,14),('Dinamarca',9,56.5,15),('Países Bajos',3,53,14),('Bélgica',2.6,50.8,14),('Suiza',7.8,46.7,14),('Eslovaquia',20,49.2,13),('Gobierno',23,52.5,13),('General',23,51.7,13),('Carelia*',33.5,64,13)]
